nav.splice(5,0,['ads','广告与归因','trend']);
const views={overview,orders:ordersView,finance:financeView,supply:supplyView,production:productionView,data:dataView,compliance:complianceView,infrastructure:infrastructureView,strategy:strategyView,ads:adsView};
let toastTimer;let dialogConfirm=null;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function render(){if(!views[route])route='overview';shell();document.querySelector('#content').innerHTML=views[route]();document.title=nav.find(n=>n[0]===route)[1]+' · 鼎匠 ONE';const periodSelect=document.querySelector('#period');if(periodSelect)periodSelect.value=period;const count=document.querySelector('.navitem .count');if(count)count.textContent=state.orders.filter(o=>o.status==='待结算').length;document.querySelectorAll('.navitem').forEach(b=>b.setAttribute('aria-current',b.dataset.route===route?'page':'false'))}
function goto(page){if(!views[page])return;document.querySelector('#dialog').close();if(location.hash.slice(1)===page){route=page;render()}else location.hash=page;window.scrollTo({top:0,behavior:'instant'})}
function modal(title,body,foot='',callback=null){const d=document.querySelector('#dialog');dialogConfirm=callback;d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="关闭弹窗">×</button></div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!d.open)d.showModal()}
function confirm(title,body,action,callback){modal(title,body,btn('取消','close')+btn(action,'confirm','primary'),callback)}
function formModal(title,body,submit,handler){modal(title,`<form id="modal-form">${body}<div class="form-error" id="form-error" role="alert"></div><div class="actions" style="justify-content:flex-end;margin-top:24px">${btn('取消','close','', 'type="button"')}<button type="submit" class="btn primary">${submit}</button></div></form>`);document.querySelector('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{handler(Object.fromEntries(new FormData(e.target)))}catch(err){document.querySelector('#form-error').textContent=err.message}})}
const field=(label,input,full=false)=>`<label class="field ${full?'full':''}">${label}${input}</label>`;
const options=()=>state.products.map(p=>`<option value="${p.sku}">${p.name} · ${p.sku}</option>`).join('');
function requireInteger(v,min,max,label){const n=Number(v);if(!Number.isInteger(n)||n<min||n>max)throw Error(`${label}必须为 ${min}–${max} 的整数`);return n}
function finish(message){document.querySelector('#dialog').close();render();toast(message)}
function newOrder(){if(!guard('supply'))return;formModal('新建订单',`<p>填写订单信息，提交后进入审核。</p><div class="form-grid">${field('销售渠道','<select class="input" name="channel"><option>Amazon US</option><option>独立站 US</option><option>独立站 EU</option><option>欧洲经销商</option></select>')}${field('产品 SKU',`<select class="input" name="sku" id="order-sku">${options()}</select>`)}${field('订购数量','<input class="input" type="number" name="qty" min="1" max="10000" step="1" value="10" required>')}${field('人民币单价（不含税）',`<input class="input" type="number" name="price" id="order-price" min="1" max="100000" step="0.01" value="560" required>`)}${field('客户代号（请勿输入个人信息）','<input class="input" name="customer" maxlength="40" value="客户 C" required>',true)}</div>`,'创建订单',v=>{if(!guard('supply'))return;const qty=requireInteger(v.qty,1,10000,'数量');const price=Number(v.price);if(!Number.isFinite(price)||price<1||price>100000)throw Error('单价须在 1–100,000 元之间');if(!product(v.sku))throw Error('请选择有效产品');const customer=v.customer.trim();if(!customer)throw Error('请输入客户代号');const id='SO-'+String(260901+state.orders.length);const o={id,channel:v.channel,biz:v.channel==='欧洲经销商'?'b2b':'b2c',region:/EU|欧洲/.test(v.channel)?'欧洲':'美国',sku:v.sku,qty,price:Math.round(price*100)/100,customer,date:'2026-09-26',status:'待审核',variance:0};state.orders.unshift(o);log('创建订单',id,`${v.sku} × ${qty}；订单金额 ${money(amount(o))}`);finish('订单已创建，可继续审核与发货。');goto('orders')})}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const audit=state.audit.filter(a=>a.object===id);modal(o.id+' · 业务追溯',`<div class="detail-grid">${[['销售渠道',o.channel],['客户代号',o.customer],['产品',product(o.sku).name],['数量',o.qty+' 件'],['订单金额',money(amount(o))],['当前状态',o.status],['归属区域',o.region],['仓库',product(o.sku).warehouse]].map(x=>`<div><span>${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div><h3 class="section-title">成本与贡献利润</h3><div class="list-row"><span>标准成本</span><strong>${money(cost(o))}</strong></div><div class="list-row"><span>平台费用 + 履约费用</span><strong>${money(fee(o)+freight(o))}</strong></div><div class="list-row"><span>费用调整 / 贡献利润</span><strong>${money(o.variance)} / ${money(profit(o))}</strong></div><p class="subtext">${o.biz==='b2b'?'TOB 结算口径：预付 / 交付后结算。':'TOC 平台或独立站渠道订单，客户信息以代号显示。'}</p><h3 class="section-title">操作记录</h3>${audit.length?audit.slice(0,5).map(a=>`<p class="subtext">${esc(a.time)} · ${esc(a.actor)}<br>${esc(a.action)}：${esc(a.detail)}</p>`).join(''):'<p class="subtext">暂无操作记录。</p>'}`,btn('关闭','close')+(o.status==='待结算'?btn('前往财务核对','to-finance','primary',`data-id="${id}"`):o.status==='已入账'?btn('查看凭证','journal-detail','primary',`data-id="${id}"`):btn(o.status==='待审核'?'审核订单':'确认发货','order-next','primary',`data-id="${id}"`)))}
function orderNext(id){if(!guard('supply'))return;const o=state.orders.find(o=>o.id===id);if(!o)return;if(o.status==='待审核'){confirm('审核订单 '+id,`<p>${product(o.sku).name} × ${o.qty} 件，金额 ${money(amount(o))}。</p><div class="notice">审核要点：核对客户代号与产品 SKU。当前可用库存 ${product(o.sku).stock} 件。审核通过后进入待发货；实际发货时再次校验库存。</div>`,'审核通过',()=>{if(!guard('supply')||o.status!=='待审核')return;o.status='待发货';log('订单审核通过',id,'客户与产品维度核对完成，进入待发货。');finish('审核完成，订单进入待发货。')})}else if(o.status==='待发货'){const p=product(o.sku);confirm('确认发货 '+id,`<p>从 ${p.warehouse} 发出 ${o.qty} 件 ${p.name}。</p><div class="notice">当前库存 ${p.stock} 件，发货后 ${p.stock-o.qty} 件。确认后更新库存，并生成待结算记录。</div>${p.stock<o.qty?'<p class="negative">库存不足，请先在供应链模块补货入库。</p>':''}`,'确认发货',()=>{if(!guard('supply')||o.status!=='待发货')return;if(p.stock<o.qty){toast('库存不足，无法发货；请先完成采购入库。');return}p.stock-=o.qty;o.status='待结算';log('订单发货',id,`${p.sku} 扣减 ${o.qty} 件，库存余量 ${p.stock}。`);finish('已扣减库存，订单已进入财务结算。')})}}
function reconcile(id){if(!guard('finance'))return;const o=state.orders.find(o=>o.id===id);if(!o||o.status!=='待结算'){toast('该订单已处理或尚未进入结算。');return}if(state.monthClosed){toast('本期已关账，请先在月结检查中重新打开账期。');return}formModal('核对结算 · ST-'+id.slice(3),`<div class="detail-grid">${[['收入',money(amount(o))],['平台费用',money(fee(o))],['履约费用',money(freight(o))],['实际到账',money(net(o))]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>${o.variance?`<div class="notice warn">实际到账比预期少 ${money(o.variance)}。必须确认差异原因，差异将计入销售费用。</div>${field('差异归因','<select class="input" name="reason" required><option value="">请选择已核实的原因</option><option>平台账单补收仓储服务费</option><option>平台账单补收履约调整费</option></select>',true)}`:`<div class="notice">结算一致，无待确认差异。</div>`}<p class="subtext">确认后生成收入、费用、到账与成本结转分录，并校验借贷平衡。</p>`,'确认并生成凭证',v=>{if(!guard('finance'))return;if(o.status!=='待结算')throw Error('此订单已完成入账');if(state.monthClosed)throw Error('本期已关账');if(o.variance&&!v.reason)throw Error('请先确认差异原因');const lines=[{account:'1002 银行存款',debit:net(o),credit:0},{account:'6601 销售费用',debit:fee(o)+freight(o)+o.variance,credit:0},{account:'6001 主营业务收入',debit:0,credit:amount(o)},{account:'6401 主营业务成本',debit:cost(o),credit:0},{account:'1405 库存商品',debit:0,credit:cost(o)}];const debit=lines.reduce((s,l)=>s+l.debit,0),credit=lines.reduce((s,l)=>s+l.credit,0);if(Math.abs(debit-credit)>.01)throw Error('借贷不平衡，已阻止入账');const j={id:'JV-202609-'+String(state.journals.length+1).padStart(4,'0'),order:id,lines,total:Math.round(debit*100)/100,reason:v.reason||'无差异',actor:role};state.journals.unshift(j);o.status='已入账';log('对账并生成凭证',id,`${j.id}；差异 ${money(o.variance)}；${j.reason}；借贷合计 ${money(j.total)}。`);finish('对账完成，已生成借贷平衡凭证。');journalDetail(id)})}
function journalDetail(order){const j=state.journals.find(j=>j.order===order);if(!j){toast('此订单尚未生成凭证。');return}modal(j.id+' · 会计凭证',`<p class="subtext">来源订单 ${j.order} · ${esc(j.actor)} · 2026 年 9 月</p><div class="table-wrap"><table><thead><tr><th>科目</th><th>借方</th><th>贷方</th></tr></thead><tbody>${j.lines.map(l=>`<tr><td>${l.account}</td><td>${l.debit?money(l.debit):'—'}</td><td>${l.credit?money(l.credit):'—'}</td></tr>`).join('')}<tr><td><strong>合计</strong></td><td><strong>${money(j.total)}</strong></td><td><strong>${money(j.total)}</strong></td></tr></tbody></table></div><div class="notice tabs-spacer">借贷平衡 · 差异归因：${esc(j.reason)}<br>分录采用标准成本与不含税金额。</div>`,btn('关闭','close')+btn('查看审计链','to-audit','primary'))}
function newPO(sku='BT100'){if(!guard('supply'))return;const p=product(sku)||product('BT100');const incoming=state.purchaseOrders.filter(x=>x.sku===p.sku&&x.status!=='已收货').reduce((s,x)=>s+x.qty,0);const recommend=Math.max(0,p.daily*30-p.stock-incoming);formModal('创建采购补货',`<div class="notice">${p.name}：30 天目标 ${p.daily*30} 件 − 可用 ${p.stock} 件 − 有效采购 ${incoming} 件 = 建议 ${recommend} 件。${recommend===0?'当前无需补货，可按业务需要调整。':''}</div><div class="form-grid">${field('采购产品',`<select class="input" name="sku" id="po-sku">${options()}</select>`)}${field('采购数量',`<input class="input" name="qty" type="number" min="1" max="100000" step="1" value="${Math.max(1,recommend)}" required>`)}${field('需求说明','<input class="input" name="reason" maxlength="100" value="海外仓补货，保障 30 天销售" required>',true)}</div><p class="subtext">审批后计入采购在途；收货后增加可用库存。</p>`,'提交采购申请',v=>{if(!guard('supply'))return;const qty=requireInteger(v.qty,1,100000,'采购数量');if(!product(v.sku))throw Error('请选择有效产品');const id='PO-2609-'+String(state.purchaseOrders.length+1).padStart(3,'0');state.purchaseOrders.unshift({id,sku:v.sku,qty,status:'待审核',reason:v.reason.trim()});log('创建采购申请',id,`${v.sku} × ${qty}；${v.reason.trim()}`);finish('采购申请已创建，等待审批。');goto('supply')});document.querySelector('#po-sku').value=p.sku}
function poNext(id){if(!guard('supply'))return;const p=state.purchaseOrders.find(p=>p.id===id);if(!p||p.status==='已收货')return;const isApproval=p.status==='待审核';confirm(isApproval?'采购审批':'采购收货确认',`<p>${id} · ${product(p.sku).name} × ${p.qty} 件</p><div class="notice">${isApproval?`采购金额 ${money(p.qty*product(p.sku).cost)}。审批通过后该批货物计入在途。`:`验收合格数量 ${p.qty} 件，确认后增加可用库存。标准单价 ${money(product(p.sku).cost)}。`}</div>`,isApproval?'批准采购':'验收并入库',()=>{if(!guard('supply'))return;if(isApproval&&p.status==='待审核'){p.status='待收货';log('采购审批通过',id,`${p.qty} 件计入采购在途。`);finish('审批完成，采购数量已计入在途。')}else if(!isApproval&&p.status==='待收货'){product(p.sku).stock+=p.qty;p.status='已收货';log('采购收货入库',id,`${p.sku} 增加 ${p.qty} 件，可用库存 ${product(p.sku).stock}。`);finish('收货完成，库存与审计记录已更新。')}})}
function newMO(){if(!guard('supply'))return;formModal('新建生产工单',`<div class="form-grid">${field('产品',`<select class="input" name="sku">${options()}</select>`)}${field('生产数量','<input class="input" type="number" name="qty" min="1" max="10000" value="100" required>')}</div><p class="subtext">工单创建时锁定 BOM 基线，按下达、报工、质检入库依次推进。</p>`,'创建工单',v=>{if(!guard('supply'))return;const qty=requireInteger(v.qty,1,10000,'数量'),p=product(v.sku);if(!p)throw Error('产品不存在');const id='MO-2609-'+String(state.workOrders.length+1).padStart(3,'0');state.workOrders.unshift({id,sku:p.sku,qty,status:'待排产',line:'装配中心',bom:p.bom.split('-').pop()});log('创建生产工单',id,`${p.sku} × ${qty}；BOM ${p.bom}`);finish('生产工单已创建。')})}
function moNext(id){if(!guard('supply'))return;const w=state.workOrders.find(w=>w.id===id);if(!w||w.status==='已完工')return;const before=w.status;const next={'待排产':'生产中','生产中':'待质检','待质检':'已完工'}[before];confirm(`${w.id} · ${next}`,`<p>${product(w.sku).name} × ${w.qty} 台，使用 BOM ${w.bom}。</p><div class="notice">${next==='已完工'?'确认全批合格后，将计入该产品的可用库存。':next==='待质检'?'确认全部报工完成，提交质量验收。':'锁定当前 BOM 版本，下达生产工单。'}</div>`,'确认'+(next==='已完工'?'合格入库':next==='待质检'?'报工':'下达'),()=>{if(!guard('supply')||w.status!==before)return;w.status=next;if(next==='已完工')product(w.sku).stock+=w.qty;log('生产工单流转',id,`${before} → ${next}；${w.sku} × ${w.qty}`);finish(next==='已完工'?'工单完工，合格成品已计入库存。':'工单状态已更新。')})}
function reviewControl(id){const c=state.controls.find(c=>c.id===id);if(!c)return;if(c.status==='已留证'){modal(c.id+' · 控制证据',`<p>${c.title}</p><div class="notice">证据索引：EV-${c.id}-2609<br>范围：${c.evidence}<br>记录类型：控制复核</div><p class="subtext">${esc(c.note||'初始记录：控制设计与证据模板已检查。')}</p>`,btn('关闭','close'));return}if(!guard('admin'))return;if(id==='FIN-02'&&state.orders.some(o=>o.status==='待结算'&&o.variance>0)){toast('仍有结算差异未闭环，请先处理财务中台中的差异订单。');return}if(id==='DR-04'&&!state.restored){toast('请先在全球基础设施生成恢复演练记录。');return}formModal(c.title,`<p>证据要求：${c.evidence}</p>${field('复核结论','<textarea class="input" name="note" rows="3" maxlength="300" required placeholder="请填写复核范围与结论"></textarea>',true)}<p class="subtext">填写复核范围、结论及证据索引。</p>`,'记录复核结论',v=>{if(!guard('admin'))return;if(v.note.trim().length<8)throw Error('请填写至少 8 个字符的复核结论');c.status='已留证';c.note=v.note.trim();log('控制复核留证',id,c.note);finish('复核记录已保存，证据状态已更新。')})}
function closeMonth(){if(!guard('finance'))return;const pending=state.orders.filter(o=>o.status==='待结算');if(state.monthClosed){confirm('2026 年 9 月已关账','<p>重新打开后可继续入账，操作将记录审计日志。</p>','重新打开账期',()=>{if(!guard('finance'))return;state.monthClosed=false;log('重新打开账期','PERIOD-202609','重新开放本期结算入账。');finish('账期已重新打开。')});return}modal('月结检查 · 2026 年 9 月',`<div class="list-row"><span>待结算订单</span>${badge(pending.length+' 笔',pending.length?'warn':'good')}</div><div class="list-row"><span>待归因费用差异</span>${badge(money(pending.reduce((s,o)=>s+o.variance,0)),pending.some(o=>o.variance)?'warn':'good')}</div><div class="list-row"><span>凭证借贷平衡</span>${badge('全部平衡','good')}</div><div class="notice tabs-spacer">${pending.length?'有未结算订单，已阻止关账。请完成对账入账后再检查。':'结算与凭证检查通过，可锁定本期入账。应收应付、存货、税务、汇兑及审批需另行复核。'}</div>`,btn('关闭','close')+(pending.length?btn('前往对账','to-finance','primary'):btn('确认关账','confirm','primary')),()=>{if(!guard('finance')||state.orders.some(o=>o.status==='待结算'))return;state.monthClosed=true;log('月结锁定','PERIOD-202609','检查通过：无待结算订单，凭证平衡。');finish('本期入账已锁定。')})}
function guide(){modal('业务流程导航',`<p>选择工作流程，进入对应业务模块。</p>${[['01','查看经营异常','经营总览 → 低库存与结算差异','overview'],['02','订单与结算','订单审核 → 发货 → 财务对账 → 凭证','orders'],['03','采购与库存','BT100 补货 → 审批 → 收货 → 库存更新','supply'],['04','治理与审计','数据修复 → 角色操作范围 → 控制证据 / 审计','compliance'],['05','建设与交付规划','公司调研 → 分层架构 → 预算与交付路线','strategy']].map(x=>`<div class="guide-step"><span class="step-num">${x[0]}</span><div><strong>${x[1]}</strong><p>${x[2]}</p></div><button class="btn small secondary" data-route="${x[3]}">进入</button></div>`).join('')}<p class="subtext">业务操作可在“合规与审计”中追溯。</p>`,btn('完成','close','primary'))}
function search(){modal('搜索工作空间','<input class="input" id="global-search" placeholder="搜索功能、订单编号或产品型号" aria-label="搜索工作空间" autocomplete="off"><div class="search-results" id="search-results"></div>');function results(q){const pages=nav.filter(n=>n[1].toLowerCase().includes(q));const orders=state.orders.filter(o=>(o.id+' '+o.sku+' '+product(o.sku).name).toLowerCase().includes(q));document.querySelector('#search-results').innerHTML=pages.map(n=>`<button data-route="${n[0]}"><span>${n[1]}</span><span class="subtext">模块 →</span></button>`).join('')+orders.slice(0,6).map(o=>`<button data-action="order-detail" data-id="${o.id}"><span>${o.id} · ${product(o.sku).name}</span><span class="subtext">${o.status}</span></button>`).join('')+(pages.length||orders.length?'':'<div class="empty">没有匹配结果。</div>')}results('');document.querySelector('#global-search').addEventListener('input',e=>results(e.target.value.trim().toLowerCase()));document.querySelector('#global-search').focus()}
function exportData(){let rows,name;if(route==='orders'){name='订单台账';rows=[['订单号','渠道','SKU','数量','人民币金额','状态'],...state.orders.map(o=>[o.id,o.channel,o.sku,o.qty,amount(o),o.status])]}else if(route==='supply'){name='库存台账';rows=[['SKU','名称','仓库','可用库存','安全库存','标准成本'],...state.products.map(p=>[p.sku,p.name,p.warehouse,p.stock,p.safety,p.cost])]}else if(route==='finance'){name='财务台账';rows=[['订单','状态','收入','标准成本','平台费','履约费','调整','净到账','贡献利润'],...state.orders.map(o=>[o.id,o.status,amount(o),cost(o),fee(o),freight(o),o.variance,net(o),profit(o)])]}else if(route==='data'){name='数据质量台账';rows=[['编号','类型','问题','标准目标','状态'],...state.quality.map(q=>[q.id,q.type,q.desc,q.target,q.status])]}else if(route==='compliance'){name='审计日志';log('导出审计记录','AUDIT-EXPORT',`导出审计日志 ${state.audit.length} 条。`);rows=[['编号','时间','角色','动作','对象','详情'],...state.audit.map(a=>[a.id,a.time,a.actor,a.action,a.object,a.detail])]}else{name='经营快照';rows=[['说明','本地业务快照；数据范围见系统说明'],['统计周期',period==='quarter'?'2026 Q3':'2026-09'],['业务筛选',filter],['营业收入（万元）',+(1286.4*(filter==='b2b'?.248:filter==='b2c'?.752:1)*(period==='quarter'?2.84:1)).toFixed(1)],['订单数',state.orders.length],['已入账笔数',state.journals.length],['可用库存',state.products.reduce((s,p)=>s+p.stock,0)]]}const csv='\ufeff'+rows.map(r=>r.map(v=>{let t=String(v??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`鼎匠-${name}-20260926.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出 '+name+'。');if(route==='compliance')render()}
function budget(id){if(!guard('admin'))return;const p=state.projects.find(p=>p.id===id);formModal('申请投入 · '+p.name,`<div class="notice">可用预算 ${p.budget-p.spent-p.committed} 万元 = 批准 ${p.budget} − 已发生 ${p.spent} − 未结承诺 ${p.committed}。</div>${field('新增承诺金额（万元）','<input class="input" type="number" name="amount" min="1" max="1000" step="1" value="10" required>')}${field('用途说明','<input class="input" name="reason" maxlength="120" placeholder="例如：区域集成试点服务" required>')}`,'提交预算检查',v=>{if(!guard('admin'))return;const n=requireInteger(v.amount,1,1000,'投入金额');if(!v.reason.trim())throw Error('请填写用途');const available=p.budget-p.spent-p.committed;if(n>available){log('预算检查拦截',id,`申请 ${n} 万元，超过可用预算 ${n-available} 万元；未新增承诺。`);throw Error(`超出可用预算 ${n-available} 万元，已拦截并留痕。请调整金额或走预算追加审批。`)}p.committed+=n;log('登记预算承诺',id,`${v.reason.trim()}；新增 ${n} 万元承诺。`);finish('预算检查通过，已登记为未结承诺。')})}
const actions={
 'close':()=>document.querySelector('#dialog').close(),
 'confirm':()=>{if(dialogConfirm){const fn=dialogConfirm;dialogConfirm=null;fn()}},
 'guide':guide,'search':search,'export':exportData,'new-order':newOrder,
 'order-detail':el=>orderDetail(el.dataset.id),'order-next':el=>orderNext(el.dataset.id),
 'to-finance':()=>{financeTab='settlements';goto('finance')},'reconcile':el=>reconcile(el.dataset.id),
 'journal-detail':el=>journalDetail(el.dataset.id),'new-po':el=>newPO(el.dataset.sku),'po-next':el=>poNext(el.dataset.id),
 'new-mo':newMO,'mo-next':el=>moNext(el.dataset.id),'close-month':closeMonth,
 'to-audit':()=>{complianceTab='audit';goto('compliance')},'control-review':el=>reviewControl(el.dataset.id),
 'menu':()=>{document.querySelector('.sidebar').classList.toggle('open');document.querySelector('.mobile-overlay').classList.toggle('visible')},
 'bom':el=>{const p=product(el.dataset.sku);modal(p.name+' · BOM',`<div class="notice">BOM ${p.bom} · 已发布基线。</div><div class="table-wrap"><table><thead><tr><th>物料项</th><th>用量</th><th>标准成本</th></tr></thead><tbody>${[['核心功能模组',.55],['主板与连接组件',.25],['外壳与包装',.12],['装配与测试',.08]].map(x=>`<tr><td>${x[0]}</td><td>1</td><td>${money(p.cost*x[1])}</td></tr>`).join('')}<tr><td><strong>合计</strong></td><td></td><td><strong>${money(p.cost)}</strong></td></tr></tbody></table></div><p class="subtext">发布后冻结版本；变更应经过研发、质量与供应链评审。生产工单记录引用版本。</p>`,btn('关闭','close'))},
 'batch':el=>{const w=state.workOrders.find(w=>w.id===el.dataset.id);modal('批次追溯 · '+w.id,`<div class="process-flow">${['BOM '+w.bom,w.id,'质量验收通过','成品入库 '+w.qty+' 台'].map(s=>`<div class="process-node">${s}</div>`).join(' → ')}</div><div class="notice">批次 LOT-${w.id} · 产品 ${w.sku}<br>生产与质检状态可从审计日志追溯。</div>`,btn('关闭','close')+btn('查看审计','to-audit','primary'))},
 'fix-data':el=>{if(!guard('admin'))return;const q=state.quality.find(q=>q.id===el.dataset.id);if(q.status==='已修复')return;confirm('审核主数据映射',`<p>${q.desc}</p><div class="notice">来源：${q.source}<br>标准目标：${q.target}<br>确认后关闭质量问题，更新评分并记录修改。</div>`,'确认标准映射',()=>{if(!guard('admin')||q.status==='已修复')return;q.status='已修复';log('修复主数据映射',q.id,`${q.desc} → ${q.target}`);finish('映射已确认，数据质量评分已更新。')})},
 'sync':el=>{if(!guard('admin'))return;const i=state.integrations.find(i=>i.id===el.dataset.id),wasFailed=i.status!=='正常';i.status='正常';i.count+=wasFailed?1:10;log(wasFailed?'重试集成消息':'数据同步完成',i.id,wasFailed?'失败消息已重试一次，处理记录已更新。':'本批次登记 10 条业务消息。');render();toast(wasFailed?'失败消息重试记录已更新。':'数据同步完成，已更新消息计数。')},
 'restore':()=>{if(!guard('admin'))return;confirm('恢复演练','<p>按预置恢复场景生成演练记录，包含耗时与完整性核对结果。</p><div class="notice">演练记录采用预置的 38 分钟结果，不执行实际服务恢复。</div>','生成演练记录',()=>{if(!guard('admin'))return;state.restored=true;log('恢复演练','DR-20260926','演练预置结果：恢复耗时 38 分钟；样本一致性通过；RTO 目标 120 分钟。');finish('恢复演练记录已生成。')})},
 'consent-allow':()=>{if(!guard('admin'))return;state.privacyConsent=true;log('授予营销同意','CMP-v1','允许营销效果测量，记录本地事件。');render();toast('当前会话已允许营销追踪。')},
 'consent-deny':()=>{if(!guard('admin'))return;state.privacyConsent=false;log('拒绝营销追踪','CMP-v1','当前会话的营销事件记录已阻断。');render();toast('当前会话已拒绝营销追踪。')},
 'test-pixel':()=>{if(!guard('admin'))return;log('购买事件检查','PIXEL-TEST',state.privacyConsent?'已同意：购买事件已写入本地日志。':'未同意：营销事件已阻断。');toast(state.privacyConsent?'购买事件检查已记录。':'营销事件已阻断，同意规则已生效。')},
 'budget':el=>budget(el.dataset.id),
 'asset':el=>modal(el.dataset.id+' · 资产详情','<div class="detail-grid"><div><span>台账类别</span><strong>IT 资产</strong></div><div><span>生命周期</span><strong>在用 · 定期复核</strong></div><div><span>责任体系</span><strong>系统 Owner + 服务商</strong></div><div><span>关联证据</span><strong>合同 / 采购 / 验收记录</strong></div></div><p class="subtext">按生命周期复核资产状态、责任人及关联合同。</p>',btn('关闭','close')),
 'reset':()=>confirm('重置本地数据','<p>本次创建的订单、采购、凭证与操作日志将被清除，并恢复预置场景。此操作仅影响当前浏览器。</p>','确认重置',()=>{state=seed();persist();filter='all';period='month';orderQuery='';statusFilter='all';financeTab='settlements';complianceTab='controls';finish('本地数据已恢复初始状态。');goto('overview')})
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-route],[data-filter],[data-action],[data-finance-tab],[data-data-tab],[data-compliance-tab],[data-strategy-tab]');if(!el)return;if(el.dataset.route){goto(el.dataset.route);return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.financeTab){financeTab=el.dataset.financeTab;render();return}if(el.dataset.dataTab){dataTab=el.dataset.dataTab;render();return}if(el.dataset.complianceTab){complianceTab=el.dataset.complianceTab;render();return}if(el.dataset.strategyTab){strategyTab=el.dataset.strategyTab;render();return}actions[el.dataset.action]?.(el)});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='role'){const before=role;role=el.value;log('切换操作角色','ROLE',`${before} → ${role}；本地页面操作范围已更新。`);render();toast('已切换为 '+role)}if(el.id==='period'){period=el.value;render()}if(el.id==='order-business'){filter=el.value;render()}if(el.id==='order-status'){statusFilter=el.value;render()}if(el.id==='ad-region'){adRegion=el.value;render()}if(el.id==='order-sku')document.querySelector('#order-price').value=product(el.value).price;if(el.id==='po-sku'){const p=product(el.value);const incoming=state.purchaseOrders.filter(x=>x.sku===p.sku&&x.status!=='已收货').reduce((s,x)=>s+x.qty,0);document.querySelector('[name="qty"]').value=Math.max(1,p.daily*30-p.stock-incoming)}});
document.addEventListener('input',e=>{if(e.target.id==='order-search'){const caret=e.target.selectionStart;orderQuery=e.target.value;render();const el=document.querySelector('#order-search');el.focus();el.setSelectionRange(caret,caret)}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'overview';render()});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_demo_state',title:'读取业务状态',description:'读取当前本地订单、库存、凭证和审计计数。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('不接受额外参数');return {orders:state.orders.length,pendingSettlements:state.orders.filter(o=>o.status==='待结算').length,journals:state.journals.length,stock:state.products.map(p=>({sku:p.sku,available:p.stock})),auditCount:state.audit.length}}});register({name:'navigate_demo_module',title:'打开业务模块',description:'切换至已有业务模块，不修改业务记录。',inputSchema:{type:'object',properties:{module:{type:'string',enum:Object.keys(views)}},required:['module'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.module!=='string'||!views[input.module]||Object.keys(input).some(k=>k!=='module'))throw Error('无效模块');goto(input.module);return {opened:input.module}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
